package org.localpilot.android;
import android.app.*;import android.os.*;import android.view.*;import android.graphics.*;import java.util.*;
public class MiniGamesActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(new Field(getIntent().getIntExtra("kind",0)));}
 private final class Field extends View {
  final int kind,n;int[] board;final Random random=new Random();final Paint p=new Paint(3);final RectF area=new RectF();int actions;
  Field(int kind){super(MiniGamesActivity.this);this.kind=kind;n=MiniPolicy.size(kind);board=new int[n*n];if(kind==1)for(int i=0;i<12;i++)board=MiniPolicy.toggle(board,random.nextInt(25));setContentDescription("LOCALPILOT_MINI_"+kind);}
  @Override protected void onDraw(Canvas c){c.drawColor(0xfffaf8ef);p.setColor(0xff37474f);p.setTextSize(38);c.drawText(kind==0?"Крестики-нолики · вы X":"Погаси свет · поле 5×5",18,60,p);p.setTextSize(24);c.drawText("Ходов: "+actions+" · панель → Привязать → Поле",18,108,p);float side=Math.min(getWidth()*.94f,getHeight()*.56f);area.set((getWidth()-side)/2,getHeight()-side-30,(getWidth()+side)/2,getHeight()-30);p.setColor(0xff90a4ae);c.drawRect(area,p);for(int i=0;i<n*n;i++){float cell=side/n,x=area.left+i%n*cell,y=area.top+i/n*cell;int[] colors=kind==0?MiniReader.TTT_COLORS:MiniReader.LIGHT_COLORS;p.setColor(0xff000000|colors[board[i]]);c.drawRect(x+5,y+5,x+cell-5,y+cell-5,p);if(kind==0&&board[i]>0){p.setColor(Color.WHITE);p.setTextSize(cell*.35f);c.drawText(board[i]==1?"X":"O",x+cell*.38f,y+cell*.63f,p);}}if(kind==0?MiniPolicy.winner(board)!=0:java.util.Arrays.stream(board).allMatch(v->v==0)){p.setColor(0xff008000);p.setTextSize(28);c.drawText(kind==0?"Раунд завершён":"Все лампы погашены",18,150,p);}}
  @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){if(area.contains(e.getX(),e.getY())){int col=(int)((e.getX()-area.left)*n/area.width()),row=(int)((e.getY()-area.top)*n/area.height()),cell=row*n+col;if(kind==1)board=MiniPolicy.toggle(board,cell);else if(MiniPolicy.winner(board)==0&&board[cell]==0){board[cell]=1;if(MiniPolicy.winner(board)==0){java.util.ArrayList<Integer> empty=new java.util.ArrayList<>();for(int i=0;i<9;i++)if(board[i]==0)empty.add(i);board[empty.get(random.nextInt(empty.size()))]=2;}}actions++;invalidate();}performClick();}return true;}
  @Override public boolean performClick(){super.performClick();return true;}
 }
}
